{
  "definition_simple": "指关于某事本身的进一步思考或描述，通常用于哲学或文艺批评中。",
  "definition_standard": "元；超越原有的层次，在更高一级的抽象层面上对事物本身进行观察、分析或表述（常作前缀，如“后设理论”、“后设叙事”）。",
  "pos": "名词/形容词",
  "semantic_class": "abstract",
  "sentences": [
    {
      "tier": "T1",
      "text": "这部电影运用了后设的手法，让角色意识到自己正在拍电影。"
    },
    {
      "tier": "T2",
      "text": "文学批评中经常讨论后设小说这种文体。"
    },
    {
      "tier": "T2",
      "text": "这是一种典型的后设思考方式。"
    },
    {
      "tier": "T3",
      "text": "后设语言是用来描述或研究普通语言的语言。"
    },
    {
      "tier": "T3",
      "text": "他在论文中探讨了后设理论在现代艺术中的应用。"
    },
    {
      "tier": "T4",
      "text": "这种后设叙事结构打破了传统叙事的第四堵墙。"
    },
    {
      "tier": "T4",
      "text": "当代哲学越来越关注后设认知层面的研究。"
    },
    {
      "tier": "T5",
      "text": "通过后设批判，他揭示了隐藏在文本背后的意识形态。"
    },
    {
      "tier": "T5",
      "text": "这部戏剧的后设特征给观众带来了独特的观剧体验。"
    },
    {
      "tier": "T6",
      "text": "后设反思的缺失往往会导致理论陷入自我封闭的循环。"
    }
  ],
