  "morphology_wrong_forms": [],
  "l1_audio_confusables": [
    {
      "word": "后撤",
      "explanation": "“后撤”发音为hòuchè，与“后设”hòushè声母不同，但在语速较快时容易被混淆。"
    },
    {
      "word": "厚社",
      "explanation": "“厚社”发音同音调略有差异或相近，容易在听力中误认。"
    },
    {
      "word": "后射",
      "explanation": "“后射”发音为hòushè，与“后设”声母韵母完全相同，仅声调可能因语境连读产生混淆。"
    }
  ],
  "primary_collocate": "叙事",
  "collocation_distractors": [
    {
      "word": "后勤",
      "explanation": "“后勤”指军队或机构的供应保障工作，与哲学或文艺批评中的“后设”毫无语义关联。"
    },
    {
      "word": "后台",
      "explanation": "“后台”多指戏剧舞台的后面或幕后势力，属于日常词汇，不能与“后设”构成学术固定搭配。"
    },
    {
      "word": "后代",
      "explanation": "“后代”指子孙后代，属于生物学或亲属称谓范畴，与抽象的元理论概念不搭。"
    }
  ],
  "collocation_wrong_collocate": "后设建筑",
  "cloze_distractors": [
    {
      "word": "假设",
      "explanation": "“假设”表示推测或假定，虽然词尾相同，但在此处无法表达元理论的高阶抽象含义。"
    },
    {
      "word": "建设",
      "explanation": "“建设”属于动宾或偏正结构的常见词，放入句中会导致语法和语义完全不通。"
    },
    {
      "word": "陈设",
      "explanation": "“陈设”指摆设的物品，属于具象名词，与句中的抽象批判语境矛盾。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "我今天在超市买了很多后设。",
      "reason": "“后设”是抽象的哲学与文艺批评概念，不能作为超市购买的具象商品。"
    },
    {
      "sentence": "这辆汽车的后设坏了，需要修理。",
      "reason": "“后设”不能用来指代汽车的零部件或物理实体。"
    },
    {
      "sentence": "请把这份文件后设一下。",
      "reason": "“后设”在此处被错误地用作动词，但它本身主要作为名词或定语修饰语使用。"
    }
  ],
  "spot_incorrect": {
    "sentence": "这部小说通过独特的后设叙事，生动地展现了古代农民的春耕生活。",
    "error_description": "“后设叙事”强调的是对叙事本身的解构、反思或关于叙事的叙事，通常具有强烈的现代主义或后现代主义色彩，与传统的、写实的古代农民春耕生活题材不匹配。",
    "corrected": "这部小说通过独特的现实主义手法，生动地展现了古代农民的春耕生活。"
  },
